param([Parameter(Mandatory=$true)][string]$MameExecutable,[Parameter(Mandatory=$true)][string]$RomDirectory,[Parameter(Mandatory=$true)][string]$RunDirectory)
$ErrorActionPreference='Stop';$run=[IO.Path]::GetFullPath($RunDirectory);if(Test-Path $run){throw 'Use a fresh isolated directory'};New-Item -ItemType Directory $run|Out-Null
foreach($name in @('cfg','nvram','inp','snap','comments','state','diff')){New-Item -ItemType Directory "$run/$name"|Out-Null}
$commands=[Collections.Generic.List[string]]::new();$cases=[Collections.Generic.List[object]]::new();$commands.Add('bpset 2851')
$body=Get-Content "$PSScriptRoot/../src/FruitMachineLab.Runtime/Mpu4PostPanelExecution.cs" -Raw
foreach($pc in ([regex]::Matches($body,'new\(0x([0-9A-F]{4}),"')|ForEach-Object {[Convert]::ToInt32($_.Groups[1].Value,16)}|Sort-Object -Unique|Where-Object {$_ -ne 0x280F})){$commands.Add(('bpset {0:X},1,{{printf "KI id=%X pc=%04X cycle=%016X bytes=%02X%02X%02X%02X%02X\n",temp1,pc,totalcycles,b@pc,b@(pc+1),b@(pc+2),b@(pc+3),b@(pc+4);go}}' -f $pc))}
foreach($variant in 0..7){foreach($level in 0..7){$id=$cases.Count;$column=$level;$tick31=@(0,255,256,257,32766,32767,32768,65535)[$variant];$sense=if($variant -band 1){1}else{0};$sample=@(0,1,2,3,4,7,254,255)[$level];$timer=@(0,1,2,65535,0,1,32768,255)[$level];$tick2d=if($level -band 1){65535}else{$id*97};$tick2f=if($level -band 2){65535}else{$id*71};$irq=if($level -band 4){255}else{$id}
 $cases.Add([ordered]@{id=$id;column=$column;tick31=$tick31;sense=$sense;sample=$sample;timer=$timer;tick2d=$tick2d;tick2f=$tick2f;irq=$irq})
 $commands.Add(('temp1=0x{0:X};pc=0x280f;cc=0x50;dp=0;s=0x700;w@28=0x{1:X};w@31=0x{2:X};w@35=0x{3:X};w@2d=0x{4:X};w@2f=0x{5:X};b@33=0x{6:X};b@0x{7:X}=0x{8:X};b@b03=0;b@b02=0xff;b@b03=4;b@b02=0x{9:X}' -f $id,$column,$tick31,$timer,$tick2d,$tick2f,$irq,(8+$column),$sample,$sense))
 $commands.Add('printf "KS id=%X pc=%04X cycle=%016X bytes=%02X%02X%02X%02X%02X\n",temp1,pc,totalcycles,b@pc,b@(pc+1),b@(pc+2),b@(pc+3),b@(pc+4)');$commands.Add('go')
 $commands.Add(('printf "KF id=%X cycle=%016X pc=%04X s=%04X tick2d=%04X tick2f=%04X tick31=%04X irq=%02X timer=%04X sample=%02X\n",temp1,totalcycles,pc,s,w@2d,w@2f,w@31,b@33,w@35,b@0x{0:X}' -f (8+$column)))
}}
$commands.Add('quit');$commands|Set-Content "$run/debugger.cmd";$cases|ConvertTo-Json|Set-Content "$run/cases.json"
[ordered]@{classification='Synthetic bounded280F counter/sense native calls; IRQ/FIRQ masked, RAM/IC4 output latch injected, ROM unpatched. Stops before2851 stack/alarm guards; no full outer-IRQ claim';mame_sha256=(Get-FileHash $MameExecutable).Hash}|ConvertTo-Json|Set-Content "$run/provenance.json"
$arguments=@('m4addr','-noreadconfig','-rompath',$RomDirectory,'-cfg_directory',"$run/cfg",'-nvram_directory',"$run/nvram",'-input_directory',"$run/inp",'-snapshot_directory',"$run/snap",'-comment_directory',"$run/comments",'-state_directory',"$run/state",'-diff_directory',"$run/diff",'-debug','-debugger','windows','-debugscript',"$run/debugger.cmd",'-debuglog','-video','none','-sound','none','-window','-skip_gameinfo','-nothrottle','-seconds_to_run','30');$arguments|ConvertTo-Json|Set-Content "$run/arguments.json"
Push-Location $run;try{& $MameExecutable @arguments *> console.txt;$code=$LASTEXITCODE;$code|Set-Content exit-code.txt}finally{Pop-Location};if($code -ne 0 -or (Select-String "$run/debug.log" -Pattern '^Error ' -Quiet)){throw 'Invalid counter/sense capture'};Write-Output $run
